            Err(TypeRefPathExtractionError::UnsupportedSyntax { location })
                if location == type_ref("(")
        ));

let paths = extract("std::vec::Vec<&'a T, [u8; N]>", &["T"], &["a"], &["N"])
            .expect("parameterized type extracts");

        assert!(paths.contains(&ExtractedTypeRefPath::Path(type_ref("std::vec::Vec"))));
        assert!(paths.contains(&ExtractedTypeRefPath::TypeParameter(ParamName::new("T").unwrap())));
        assert!(
            paths.contains(&ExtractedTypeRefPath::LifetimeParameter(ParamName::new("a").unwrap()))
        );
        assert!(
            paths.contains(&ExtractedTypeRefPath::ConstParameter(ParamName::new("N").unwrap()))
        );
        assert!(paths.contains(&ExtractedTypeRefPath::Path(type_ref("u8"))));
        assert!(!paths.iter().any(|path| {
            matches!(path, ExtractedTypeRefPath::Path(path) if matches!(path.as_str(), "T" | "a" | "N"))
        }));

assert!(matches!(
            extract("(", &[], &[], &[]),
            Err(TypeRefPathExtractionError::UnsupportedSyntax { location })
                if location == type_ref("(")
        ));

.expect_err("ambiguous short name must fail");

        assert!(matches!(
            error,
            CatalogueIdentityResolutionError::AmbiguousIdentifier(identifier, candidates)
                if identifier.as_str() == "Entity"
                    && candidates.as_slice() == [first, second]
        ));

        .expect_err("unresolved path must fail");

        assert!(matches!(
            error,
            CatalogueIdentityResolutionError::UnresolvedIdentifier(unresolved)
                if unresolved.as_str() == "domain::beta::Entity"
        ));

assert!(
            !violations
                .iter()
                .any(|violation| { violation.entry_name() == "domain::alpha::Parameterized" })
        );
        for (entry_name, location) in [
            ("domain::alpha::DepthLimited", "depth_limited"),
            ("domain::alpha::PartialInspection", "partially_inspected"),
            ("domain::alpha::Unclassifiable", "UnknownBarePath"),
        ] {
            let violation =
                violations.iter().find(|violation| violation.entry_name() == entry_name).unwrap();
            assert!(violation.message().contains(location));
        }

assert!(
            !violations
                .iter()
                .any(|violation| { violation.entry_name() == "domain::alpha::Parameterized" })
        );
        for (entry_name, location) in [
            ("domain::alpha::DepthLimited", "depth_limited"),
            ("domain::alpha::PartialInspection", "partially_inspected"),
            ("domain::alpha::Unclassifiable", "UnknownBarePath"),
        ] {
            let violation =
                violations.iter().find(|violation| violation.entry_name() == entry_name).unwrap();
            assert!(violation.message().contains(location));
        }

assert_eq!(
            paths,
            vec![
                ExtractedTypeRefPath::Path(type_ref("std::result::Result")),
                ExtractedTypeRefPath::Path(type_ref("domain::alpha::Event")),
                ExtractedTypeRefPath::Path(type_ref("domain::beta::Event")),
            ]
        );
